/* 双线性取一个源样本（g 为灰度，a 为 alpha，均 0..255） */
static void ci_sample(double u, double v, double *g, double *a)
{
    double x = u * (double)CI_N - 0.5, y = v * (double)CI_N - 0.5;
    int x0, y0;
    double fx, fy, g00, g10, g01, g11, a00, a10, a01, a11, w;
    const unsigned char *p;

    if (x < 0.0) x = 0.0;
    if (x > (double)CI_N - 1.0) x = (double)CI_N - 1.0;
    if (y < 0.0) y = 0.0;
    if (y > (double)CI_N - 1.0) y = (double)CI_N - 1.0;
    x0 = (int)x; y0 = (int)y;
    fx = x - x0; fy = y - y0;
    if (x0 >= CI_N - 1) { x0 = CI_N - 2; fx = 1.0; }
    if (y0 >= CI_N - 1) { y0 = CI_N - 2; fy = 1.0; }

#define CI_AT(xx, yy) (ci_data + ((size_t)(yy) * CI_N + (xx)) * 2)
    p = CI_AT(x0, y0);     g00 = p[0]; a00 = p[1];
    p = CI_AT(x0 + 1, y0); g10 = p[0]; a10 = p[1];
    p = CI_AT(x0, y0 + 1); g01 = p[0]; a01 = p[1];
    p = CI_AT(x0 + 1, y0 + 1); g11 = p[0]; a11 = p[1];
#undef CI_AT
    w = (1.0 - fx) * (1.0 - fy);
    *g = g00 * w + g10 * fx * (1.0 - fy) +
         g01 * (1.0 - fx) * fy + g11 * fx * fy;
    w = (1.0 - fx) * (1.0 - fy);
    *a = a00 * w + a10 * fx * (1.0 - fy) +
         a01 * (1.0 - fx) * fy + a11 * fx * fy;
}

void capsule_icon_draw(Canvas *c, double cx, double cy, double d, double k)
{
    static const double off[4][2] = {
        {-0.25, -0.25}, {0.25, -0.25}, {-0.25, 0.25}, {0.25, 0.25}
    };
    double left = cx - d * 0.5, top = cy - d * 0.5;
    int x0 = (int)floor(left), x1 = (int)ceil(left + d);
    int y0 = (int)floor(top),  y1 = (int)ceil(top + d);
    int x, y;

    if (!c || d <= 0.5 || k <= 0.002) return;
    for (y = y0; y < y1; y++) {
        for (x = x0; x < x1; x++) {
            double ga = 0.0, aa = 0.0, g, al;
            int s;
            for (s = 0; s < 4; s++) {
                double px = (double)x + 0.5 + off[s][0];
                double py = (double)y + 0.5 + off[s][1];
                double u = (px - left) / d, v = (py - top) / d;
                if (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0) continue;
                ci_sample(u, v, &g, &al);
                
                ga += g * al / 255.0;
                aa += al / 255.0;
            }
            if (aa <= 0.0) continue;
            g  = ga / aa;              /* 0..255 */
            al = aa * 0.25 * k;       /* 四个子样本平均覆盖率 */
            canvas_blend_px(c, x, y, (int)(g + 0.5), (int)(g + 0.5),
                            (int)(g + 0.5), al);
        }
    }
}
